# VULNERABLE: fetch raw page, dump it into context, keep all tools live.
def summarize_url(url):
    html = requests.get(url).text          # no allowlist, follows anywhere
    return agent.run(f"Summarize this page:\n{html}", tools=ALL_TOOLS)


# SAFER: restrict targets, strip to visible text, fence as untrusted, limit tools.
ALLOWED_HOSTS = {"docs.example.com", "news.example.com"}

def summarize_url(url):
    host = urlparse(url).hostname
    if host not in ALLOWED_HOSTS:
        raise ValueError("URL not allowed")
    if is_internal_ip(host):               # block SSRF to internal/metadata IPs
        raise ValueError("Internal address blocked")
    text = extract_visible_text(requests.get(url).text)  # drop hidden nodes/comments
    fenced = f"<UNTRUSTED_WEB_DATA>\n{text}\n</UNTRUSTED_WEB_DATA>"
    return agent.run(f"Summarize:\n{fenced}", tools=READ_ONLY_TOOLS)
